<script>
function layoutEditor(){return {paperW:@json((float)($layout->paper_width_mm ?? 210)),paperH:@json((float)($layout->paper_height_mm ?? 297)),scale:2.5,fields:@json($initialFields),masks:@json($initialMasks),labels:@json($catalog),assetUrls:{association_seal:@json($layout?->seal_path ? asset('storage/'.$layout->seal_path) : null),chairman_signature:@json($layout?->signature_path ? asset('storage/'.$layout->signature_path) : null)},newKey:'',selectedField:null,selectedMask:null,drag:null,backgroundUrl:@json($layout?->background_path ? asset('storage/'.$layout->background_path) : null),addField(){if(!this.newKey)return;let image=['association_seal','chairman_signature'].includes(this.newKey);let f={field_key:this.newKey,x_mm:10,y_mm:10,width_mm:image?35:55,height_mm:image?25:8,font_size_pt:11,font_family:'Tahoma',text_align:'center',rotation_deg:0,is_bold:false,show_on_original:this.newKey!=='serial_number',show_on_copy:true};this.fields.push(f);this.selectedField=f;this.selectedMask=null},addMask(){let m={label:'پوشاندن شماره نمونه',x_mm:10,y_mm:10,width_mm:40,height_mm:8,color:'#ffffff'};this.masks.push(m);this.selectedMask=m;this.selectedField=null},removeSelected(){this.fields=this.fields.filter(f=>f!==this.selectedField);this.selectedField=null},removeSelectedMask(){this.masks=this.masks.filter(m=>m!==this.selectedMask);this.selectedMask=null},boxStyle(o){return `left:${o.x_mm*this.scale}px;top:${o.y_mm*this.scale}px;width:${o.width_mm*this.scale}px;height:${o.height_mm*this.scale}px;transform:rotate(${o.rotation_deg||0}deg)`},startDrag(e,o){this.drag={o,sx:e.clientX,sy:e.clientY,ox:+o.x_mm,oy:+o.y_mm}},dragMove(e){if(!this.drag)return;this.drag.o.x_mm=Math.max(0,+(this.drag.ox+(e.clientX-this.drag.sx)/this.scale).toFixed(1));this.drag.o.y_mm=Math.max(0,+(this.drag.oy+(e.clientY-this.drag.sy)/this.scale).toFixed(1))},previewFile(e){let f=e.target.files[0];if(f)this.backgroundUrl=URL.createObjectURL(f)},previewAsset(e,key){let f=e.target.files[0];if(f)this.assetUrls[key]=URL.createObjectURL(f)},syncJson(){}}}
</script>
